// ─── Regulated devices (plan A12) ────────────────────────────────────────────
//
// A device is one approval in one jurisdiction and covers system releases (`covers`). The Documents page lists
// them with the releases each covers; the documents themselves are generated by the server from those releases.
// A device's kind is matched through the kind registry, so a specialization counts.
// ─────────────────────────────────────────────────────────────────────────────

import { indexKinds, kindConformsTo, relationshipsOfType, type MemoModelDTO } from '@memoarchitect/tools/browser';
import { idsInWorkspace } from './workspace-scope';

export const DEVICE_KIND = 'RegulatedDevice';

export interface DeviceRow {
    id: string;
    name: string;
    jurisdiction: string;
    submissionId?: string;
    /** The releases it covers, with the commit each pins. */
    covers: { id: string; name: string; commit: string }[];
}

export function regulatedDevices(model: MemoModelDTO, workspace: string | null): DeviceRow[] {
    const kinds = indexKinds(model.registries?.kinds ?? []);
    const inWorkspace = idsInWorkspace(model.workspaceMembership, workspace);
    const covers = relationshipsOfType(model, 'covers');
    return Object.values(model.elements)
        .filter(e => kindConformsTo(e.kind, DEVICE_KIND, kinds) && (!inWorkspace || inWorkspace.has(e.id)))
        .map(e => ({
            id: e.id, name: e.name || e.id.slice(e.id.lastIndexOf('::') + 2),
            jurisdiction: (e.attributes.jurisdiction ?? '').replace(/^.*::/, ''),
            submissionId: e.attributes.submissionId || undefined,
            covers: covers.filter(r => r.sourceId === e.id).map(r => ({
                id: r.targetId, name: model.elements[r.targetId]?.name || r.targetId,
                commit: (model.elements[r.targetId]?.attributes.modelCommit ?? '').slice(0, 7),
            })),
        }))
        .sort((a, b) => a.name.localeCompare(b.name));
}

/**
 * Which features are offered in which market: a feature is offered in a jurisdiction when a device of that
 * jurisdiction covers a release that selects it. `releases` are the records' selected features, by record id.
 */
export function featuresByMarket(devices: DeviceRow[], selectedBy: (recordId: string) => string[]): { jurisdictions: string[]; offered: Map<string, Set<string>> } {
    const offered = new Map<string, Set<string>>();
    for (const device of devices) {
        for (const cover of device.covers) {
            for (const feature of selectedBy(cover.id)) {
                const markets = offered.get(feature) ?? new Set<string>();
                markets.add(device.jurisdiction || '—');
                offered.set(feature, markets);
            }
        }
    }
    const jurisdictions = [...new Set(devices.map(d => d.jurisdiction || '—'))].sort();
    return { jurisdictions, offered };
}
